<?php $edit=isset($record['id']);$val=fn($k)=>e($record[$k]??'');?><div class="admin-pagehead"><div><span class="micro-label">GESTIÓN DE CAMPAÑAS</span><h1><?= $edit?'Editar campaña':'Crear campaña' ?></h1><p>Las campañas nuevas permanecen en borrador hasta su revisión.</p></div><a class="btn btn-outline" href="/admin/campanas">← Campañas</a></div><section class="admin-panel"><form method="post" class="editor-form" action="<?= $edit?'/admin/campanas/'.(int)$record['id'].'/editar':'/admin/campanas' ?>"><?= csrf_field() ?><div class="form-pair"><label>Tipo<select name="tipo"><?php foreach(['general','individual'] as $v):?><option value="<?= $v ?>" <?= ($record['tipo']??'general')===$v?'selected':'' ?>><?= e(ucfirst($v)) ?></option><?php endforeach ?></select></label><label>Animal (solo para tipo individual)<select name="animal_id"><option value="">Sin animal específico</option><?php foreach($animals as $a):?><option value="<?= (int)$a['id'] ?>" <?= ($record['animal_id']??'')==$a['id']?'selected':'' ?>><?= e($a['nombre']) ?></option><?php endforeach ?></select></label></div><label>Título *<input name="titulo" maxlength="150" required value="<?= $val('titulo') ?>"></label><label>Necesidad a cubrir *<input name="necesidad" maxlength="150" required value="<?= $val('necesidad') ?>"></label><label>Descripción completa *<textarea name="descripcion" required><?= $val('descripcion') ?></textarea></label><div class="form-pair"><label>Categoría<select name="categoria"><?php foreach(['alimentacion','atencion_veterinaria','infraestructura','mantenimiento','limpieza','alquiler','servicios_basicos','otro'] as $v):?><option value="<?= $v ?>" <?= ($record['categoria']??'otro')===$v?'selected':'' ?>><?= e(str_replace('_',' ',$v)) ?></option><?php endforeach ?></select></label><label>Meta en Bs (opcional)<input type="number" name="meta_monto" min="0.01" step="0.01" value="<?= $val('meta_monto') ?>"></label></div><div class="form-pair"><label>Fecha de inicio<input type="date" name="fecha_inicio" value="<?= $val('fecha_inicio') ?>"></label><label>Fecha de cierre<input type="date" name="fecha_fin" value="<?= $val('fecha_fin') ?>"></label></div><div class="form-pair"><label>Estado<select name="estado"><?php foreach(['borrador','activa','pausada','finalizada','cancelada'] as $v):?><option value="<?= $v ?>" <?= ($record['estado']??'borrador')===$v?'selected':'' ?>><?= e(ucfirst($v)) ?></option><?php endforeach ?></select></label><label class="toggle-row"><input type="checkbox" name="es_permanente" value="1" <?= !empty($record['es_permanente'])?'checked':'' ?>><span>Campaña permanente</span></label></div><label class="toggle-row"><input type="checkbox" name="contenido_verificado" value="1"><span>He revisado y confirmado que esta campaña puede publicarse.</span></label><button class="btn btn-primary" type="submit">Guardar campaña ↗</button></form></section>
